using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using SDGAdventure.Level04;
public static class Level04WallGunAudit {
 static string PathOf(Transform t){string s=t.name;while(t.parent){t=t.parent;s=t.name+"/"+s;}return s;}
 [MenuItem("SDG Adventure/Level04/Probe Wall Guns")]
 public static void Probe(){
  var scene=Application.isBatchMode?EditorSceneManager.OpenScene("Assets/_Modules_/02_Levels/Level04/Imported/Scenes/SampleScene.unity",OpenSceneMode.Single):UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(scene.path!="Assets/_Modules_/02_Levels/Level04/Imported/Scenes/SampleScene.unity"||scene.isDirty)throw new Exception("Open the saved Level04 scene first");Physics.SyncTransforms();
  foreach(var t in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).Where(t=>t.name.Contains("Plasma")||t.name=="WeaponPickup"||t.name=="PickupTrigger")){var b=t.GetComponent<Behaviour>();Debug.Log("WALLGUN_OBJECT path="+PathOf(t)+" pos="+t.position.ToString("F3")+" rot="+t.eulerAngles.ToString("F3")+" scale="+t.lossyScale.ToString("F3")+" active="+t.gameObject.activeInHierarchy+" prefab="+(PrefabUtility.GetCorrespondingObjectFromSource(t.gameObject)?PrefabUtility.GetCorrespondingObjectFromSource(t.gameObject).name:"none")+" pickup="+(t.GetComponent<Level04PlasmaPickup>()!=null));foreach(var c in t.GetComponents<Collider>())Debug.Log("WALLGUN_COLL path="+PathOf(t)+" enabled="+c.enabled+" trigger="+c.isTrigger+" bounds="+c.bounds);}
  var pickup=UnityEngine.Object.FindObjectsOfType<Level04PlasmaPickup>(true).Single();var model=pickup.transform.Find("PlasmaSMG_Model");var rr=model.GetComponentsInChildren<Renderer>(true);var bounds=rr[0].bounds;foreach(var r in rr.Skip(1))bounds.Encapsulate(r.bounds);Debug.Log("WALLGUN_BOUNDS "+bounds);
  foreach(float x in new[]{-15.87f,-17.49f,-19f})foreach(float y in new[]{1.5f,2.12f,2.7f})foreach(var hit in Physics.RaycastAll(new Vector3(x,y,-4),Vector3.forward,8,~0,QueryTriggerInteraction.Ignore).OrderBy(h=>h.distance))if(!hit.collider.transform.IsChildOf(pickup.transform))Debug.Log("WALLGUN_RAY x="+x+" y="+y+" hit="+PathOf(hit.collider.transform)+" point="+hit.point.ToString("F3")+" normal="+hit.normal.ToString("F3"));
 }
 public static void Apply(){
  var scene=EditorSceneManager.OpenScene("Assets/_Modules_/02_Levels/Level04/Imported/Scenes/SampleScene.unity",OpenSceneMode.Single);var pickup=UnityEngine.Object.FindObjectsOfType<Level04PlasmaPickup>(true).Single();var box=pickup.GetComponent<BoxCollider>();var model=pickup.transform.Find("PlasmaSMG_Model");if(!box||!model||box.isTrigger)throw new Exception("Unexpected gun setup");var old=pickup.transform.position;Physics.SyncTransforms();var renderers=model.GetComponentsInChildren<Renderer>(true).Where(r=>r.enabled).ToArray();if(renderers.Length==0)throw new Exception("Missing gun renderers");var bounds=renderers[0].bounds;foreach(var r in renderers.Skip(1))bounds.Encapsulate(r.bounds);var wall=Physics.RaycastAll(new Ray(bounds.center,Vector3.forward),4,~0,QueryTriggerInteraction.Ignore).Where(h=>!h.collider.transform.IsChildOf(pickup.transform)&&h.collider.name=="factory"&&h.normal.z<-.9f).OrderBy(h=>h.distance).FirstOrDefault();if(!wall.collider)throw new Exception("Expected wall not found");box.center=pickup.transform.InverseTransformPoint(bounds.center);box.size=new Vector3(Mathf.Max(.35f,bounds.size.x),Mathf.Max(.35f,bounds.size.y),bounds.size.z);float move=wall.point.z-bounds.max.z-.005f;if(move<0||move>3f)throw new Exception("Unexpected wall gap");pickup.transform.position+=Vector3.forward*move;Physics.SyncTransforms();var collision=Physics.OverlapBox(box.bounds.center,box.bounds.extents*.98f,Quaternion.identity,~0,QueryTriggerInteraction.Ignore).Where(c=>!c.transform.IsChildOf(pickup.transform)).ToArray();if(collision.Length>0)throw new Exception("Gun overlaps: "+string.Join(",",collision.Select(c=>c.name)));var hits=Physics.RaycastAll(box.bounds.center+Vector3.back*2,Vector3.forward,3,~0,QueryTriggerInteraction.Ignore).OrderBy(h=>h.distance).ToArray();if(hits.Length==0||hits[0].collider!=box)throw new Exception("Wall obstructs player interaction");EditorSceneManager.MarkSceneDirty(scene);if(!EditorSceneManager.SaveScene(scene))throw new Exception("Scene save failed");Debug.Log("WALLGUN_FIXED before="+old.ToString("F4")+" after="+pickup.transform.position.ToString("F4")+" model="+model.position.ToString("F4")+" wall="+wall.point.ToString("F4")+" collider="+box.bounds+" gap="+(wall.point.z-(bounds.max.z+move)).ToString("F4"));
 }
}
